DROP ALL OBJECTS;
CREATE TABLE warehouse(id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) UNIQUE,name VARCHAR(100),address VARCHAR(255),status VARCHAR(20),remark VARCHAR(500),create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE warehouse_area(id BIGINT AUTO_INCREMENT PRIMARY KEY,warehouse_id BIGINT,code VARCHAR(32) UNIQUE,name VARCHAR(100),polygon CLOB,remark VARCHAR(500),create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE shelf(id BIGINT AUTO_INCREMENT PRIMARY KEY,area_id BIGINT,code VARCHAR(32) UNIQUE,name VARCHAR(100),row_count INT,column_count INT,remark VARCHAR(500),create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE camera(id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) UNIQUE,name VARCHAR(100),rtsp_url VARCHAR(500),install_position VARCHAR(255),area_id BIGINT,monitor_target VARCHAR(255),online_status TINYINT,remark VARCHAR(500),create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE slot(id BIGINT AUTO_INCREMENT PRIMARY KEY,warehouse_id BIGINT,shelf_id BIGINT,camera_id BIGINT,code VARCHAR(32) UNIQUE,polygon CLOB,status VARCHAR(20),cargo_type VARCHAR(64),last_update_time TIMESTAMP,remark VARCHAR(500),create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE detection_result(id BIGINT AUTO_INCREMENT PRIMARY KEY,camera_id BIGINT,captured_at TIMESTAMP,objects_json CLOB,image_url VARCHAR(500),create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE warehouse_event(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_type VARCHAR(32),camera_id BIGINT,slot_id BIGINT,object_type VARCHAR(64),actor_type VARCHAR(32),confidence DECIMAL(6,5),image_url VARCHAR(500),event_time TIMESTAMP,status VARCHAR(20),remark VARCHAR(500),create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE slot_state_history(id BIGINT AUTO_INCREMENT PRIMARY KEY,slot_id BIGINT,previous_status VARCHAR(20),current_status VARCHAR(20),source VARCHAR(20),event_id BIGINT,changed_at TIMESTAMP,remark VARCHAR(500),create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE alarm(id BIGINT AUTO_INCREMENT PRIMARY KEY,alarm_type VARCHAR(64),location VARCHAR(255),level VARCHAR(20),trigger_time TIMESTAMP,image_url VARCHAR(500),status VARCHAR(20),handler VARCHAR(64),handled_at TIMESTAMP,remark VARCHAR(500),create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE person_state(id BIGINT AUTO_INCREMENT PRIMARY KEY,person_id VARCHAR(64),camera_id VARCHAR(32),state VARCHAR(20),risk_score DECIMAL(5,4),visual_weight DECIMAL(5,4),audio_weight DECIMAL(5,4),text_weight DECIMAL(5,4),behavior_weight DECIMAL(5,4),environment_weight DECIMAL(5,4),timestamp TIMESTAMP,create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE `user`(id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(64) UNIQUE,password VARCHAR(255),real_name VARCHAR(64),role VARCHAR(32),status TINYINT,create_time TIMESTAMP,update_time TIMESTAMP);
CREATE TABLE discipline_record(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id BIGINT UNIQUE,person_id VARCHAR(64),action_type VARCHAR(20),points INT,warning_level VARCHAR(20),reason VARCHAR(500),reviewer VARCHAR(64),reviewed_at TIMESTAMP,create_time TIMESTAMP,update_time TIMESTAMP);
